54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
60	
61	    private final ClinicService clinicService;
