107	    /**
108	     * Whether more than 80 owners have already been created on {@code registrationDate},
109	     * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
110	     */
111	    private boolean isBulkSignup(LocalDate registrationDate) {
112	        return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
113	    }
