115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        LocalDate registrationDate = owner.resolveRegistrationDate();
121	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
122	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
123	        }
124	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        // The household id is deterministic: owners that share a (normalized lastName, postcode)
128	        // share it automatically. It feeds the identity key and the household-duplicate rule below.
129	        owner.setHouseholdId(this.clinicService.computeHouseholdId(owner));
130	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
131	        boolean householdExists = this.clinicService.existsOwnerInHousehold(owner.getHouseholdId());
132	        // Household duplicate: another owner already shares this (lastName, postcode). Rejected unless
133	        // the caller declares they share the household ('sharesHousehold' only bypasses this block).
134	        if (householdExists && !sharesHousehold) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        // Hard duplicate detection is consolidated into the owner's derived identity key (see
138	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
139	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        // Soft-match: shares an existing owner's lastName and postcode with a different telephone,
143	        // flagged 'possibleDuplicate'. A declared household member is not a suspected duplicate, so
144	        // the flag is suppressed when this owner joins an existing household.
145	        Integer possibleDuplicateOf = householdExists ? null
146	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
147	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
148	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
149	        owner.setNamesakeCount(
150	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
151	        this.clinicService.saveOwner(owner);
152	        owner.setHouseholdSize(this.clinicService.countOwnersByHouseholdId(owner.getHouseholdId()));
153	        auditLogger.info("owner created: id={} customerCode={} registrationDate={}",
154	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
