248	    /** Fixed city-to-region table used to derive an owner's region for its customer code. */
249	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
250	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
251	
252	    /** Region to inclusive 4-digit postcode range {low, high}, preferred over the city table
253	     *  when deriving an owner's region. */
254	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
255	        "NSW", new int[] {2000, 2099},
256	        "VIC", new int[] {3000, 3099},
257	        "QLD", new int[] {4000, 4099});
258	
259	    /**
260	     * Builds an owner's customer code formatted {@code '<REGION>-<HASH8>'}, where REGION is the
261	     * region code derived from the owner's postcode (see {@link #deriveRegion(Owner)}) and HASH8 is
262	     * the first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized
263	     * telephone concatenated with its last name (e.g. {@code 'NSW-1A2B3C4D'}). The old per-city
264	     * sequence numbers have been dropped: the identity is now purely region-and-hash.
265	     */
266	    private String generateCustomerCode(Owner owner) {
267	        return String.format("%s-%s", deriveRegion(owner), hash8(owner));
268	    }
269	
270	    /**
271	     * Derives an owner's region code, preferring the postcode: the region whose inclusive 4-digit
272	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used first. When
273	     * the postcode is absent or in no known range, it falls back to the fixed city-to-region table
274	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the
275	     * city is not in the table.
276	     */
277	    private static String deriveRegion(Owner owner) {
278	        String postcode = owner.getPostcode();
279	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
280	            int value = Integer.parseInt(postcode);
281	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
282	                int[] range = entry.getValue();
283	                if (value >= range[0] && value <= range[1]) {
284	                    return entry.getKey();
285	                }
286	            }
287	        }
288	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
289	    }
290	
291	    /**
292	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
293	     * digest over its normalized telephone concatenated with its last name.
294	     */
295	    private static String hash8(Owner owner) {
296	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
297	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
298	        String seed = telephone + lastName;
299	        try {
300	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
301	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
302	            StringBuilder sb = new StringBuilder(hash.length * 2);
303	            for (byte b : hash) {
304	                sb.append(String.format("%02X", b));
305	            }
306	            return sb.substring(0, 8);
307	        }
308	        catch (NoSuchAlgorithmException e) {
309	            throw new IllegalStateException("SHA-256 not available", e);
310	        }
311	    }
