313	    /**
314	     * Whether any existing owner has the given derived identity key. This is the single basis for
315	     * duplicate detection: a create is rejected only when the whole key matches an existing owner
316	     * exactly. See {@link Owner#getIdentityKey()} for the key's definition.
317	     */
318	    @Override
319	    @Transactional(readOnly = true)
320	    public boolean existsOwnerWithIdentityKey(String identityKey) throws DataAccessException {
