339	        if (owner == null || owner.getLastName() == null || owner.getPostcode() == null) {
340	            return null;
341	        }
342	        String lastName = owner.getLastName();
343	        String postcode = owner.getPostcode();
344	        String telephone = owner.getTelephone();
345	        return ownerRepository.findAll().stream()
346	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName())
347	                && postcode.equals(existing.getPostcode())
348	                && !Objects.equals(telephone, existing.getTelephone()))
349	            .map(Owner::getId)
350	            .filter(Objects::nonNull)
351	            .min(Comparator.naturalOrder())
352	            .orElse(null);
