401	    /**
402	     * Computes an owner's deterministic household id: the first 12 upper-case hex characters of the
403	     * SHA-256 digest over the owner's normalized last name, a {@code '|'} separator and its postcode
404	     * ({@code normalizedLastName + '|' + postcode}). Owners that share a last name and postcode
405	     * therefore map to the same household id automatically, without any explicit linking. Returns
406	     * {@code null} when the last name or postcode is absent or blank, since no household can be
407	     * formed without both.
408	     */
409	    @Override
410	    @Transactional(readOnly = true)
411	    public String computeHouseholdId(Owner owner) throws DataAccessException {
412	        if (owner == null) {
413	            return null;
414	        }
415	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
416	        String postcode = owner.getPostcode();
417	        if (normalizedLastName == null || normalizedLastName.isBlank()
418	            || postcode == null || postcode.isBlank()) {
419	            return null;
420	        }
421	        return sha256UpperHex(normalizedLastName + "|" + postcode, 12);
422	    }
423	
424	    /**
425	     * Whether any existing owner already belongs to the household identified by the given
426	     * (deterministic) household id. This is the single basis for the household-duplicate rule:
427	     * owners that share a last name and postcode share a household id, so a matching existing owner
428	     * means the new owner is a household duplicate. Returns {@code false} when the id is absent.
429	     */
430	    @Override
