432	    public boolean existsOwnerInHousehold(String householdId) throws DataAccessException {
433	        if (householdId == null || householdId.isBlank()) {
434	            return false;
435	        }
436	        return ownerRepository.findAll().stream()
437	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
438	    }
439	
440	    /**
441	     * Counts the owners that belong to the household identified by the given (deterministic)
442	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
443	     * the membership-points calculation. Returns {@code 0} when the id is absent.
444	     */
445	    @Override
446	    @Transactional(readOnly = true)
447	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
448	        if (householdId == null || householdId.isBlank()) {
449	            return 0;
450	        }
451	        return (int) ownerRepository.findAll().stream()
452	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
453	            .count();
454	    }
455	
456	    /**
457	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
458	     * runs of whitespace to a single space and lower-casing, so values that differ only in
459	     * whitespace or letter case are treated as equal.
460	     */
461	    private static String normalizeHouseholdField(String value) {
462	        if (value == null) {
463	            return null;
464	        }
465	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
466	    }
467	
468	    /**
469	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
470	     * UTF-8 bytes of {@code seed}.
471	     */
472	    private static String sha256UpperHex(String seed, int length) {
473	        try {
474	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
475	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
476	            StringBuilder sb = new StringBuilder(hash.length * 2);
477	            for (byte b : hash) {
478	                sb.append(String.format("%02X", b));
479	            }
480	            return sb.substring(0, length);
481	        }
482	        catch (NoSuchAlgorithmException e) {
483	            throw new IllegalStateException("SHA-256 not available", e);
484	        }
485	    }
